import re

LINE = re.compile(r"^(?P<ts>\S+)\s+(?P<level>[A-Z]+)\s+(?P<msg>.*)$")


def parse(text: str) -> list[dict]:
    out = []
    for line in text.splitlines():
        if not line.strip():
            continue
        if line[0].isspace() and out:
            out[-1]["msg"] += " " + line.strip()
            continue
        m = LINE.match(line)
        if not m:
            raise ValueError(f"unexpected line: {line!r}")
        out.append(m.groupdict())
    return out


def summarize(rows: list[dict]) -> dict:
    counts: dict[str, int] = {}
    for r in rows:
        counts[r["level"]] = counts.get(r["level"], 0) + 1
    return counts
=== CLI ===
import sys

from .parser import parse, summarize


def main(argv: list[str]) -> int:
    if not argv:
        print("usage: cli <logfile>")
        return 1
    rows = parse(open(argv[0]).read())
    for level, n in sorted(summarize(rows).items()):
        print(f"{level:>7} {n}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
